
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mbrxh_bg_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mbrxh_bg", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.128756940171004e+00, -4.062618323910986e+00, -3.971683964744369e+00, -3.849614030274723e+00, -3.692013163829667e+00, -3.500393852891062e+00, -3.279680870744698e+00, -3.019209834300923e+00, -2.718464402682231e+00, -2.401460454600545e+00, -1.836034957185218e+00, -8.632015233417143e-01, -5.990255736988458e-01, -5.443563837014824e-01, -4.963638840189318e-01, -4.709789005591106e-01, -5.621924363818690e-01, -9.681138705066151e-01, -2.708448970991327e+00, -1.493993408699546e+01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


